<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?><div class="auth-page container"><form class="form-card" method="post" action="/login"><p class="eyebrow">Tài khoản</p><h1>Đăng nhập</h1><?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?><?= Csrf::field() ?><label for="email">Email</label><input id="email" name="email" type="email" value="<?= ViewHelper::escape($email ?? '') ?>" required><label for="password">Mật khẩu</label><input id="password" name="password" type="password" required><button class="button button-primary" type="submit">Đăng nhập</button><a class="button google-login-button" href="/auth/google">Tiếp tục với Google</a><p>Chưa có tài khoản? <a href="/register">Đăng ký</a></p></form></div>
